// Values added per frame on top of CanvasDrawParams, plus the cached radial geometry the Radial gradient writes back.
export interface DrawFrame {
  ctx: CanvasRenderingContext2D;
  canvas: HTMLCanvasElement;
  fieldAnimTime: number; auroraAnimTime: number; turrellAnimTime: number; causticsAnimTime: number; lavaAnimTime: number;
  marbleAnimTime: number; metaballAnimTime: number; flowAnimTime: number; attractorAnimTime: number; liquidAnimTime: number;
  emojiAnimTime: number; hatchAnimTime: number; noiseAnimTime: number; radialAnimTime: number; voronoiAnimTime: number; flowerAnimTime: number;
  centerX: number; centerY: number; maxRadius: number; fitRadius: number;
  angleRad: number; cosAngle: number; sinAngle: number;
  displayWidth: number; displayHeight: number;
  putScaledImageData: (imgData: ImageData, dx?: number, dy?: number) => void;
  getDisplayImageData: () => ImageData;
  putLowResImageData: (imgData: ImageData) => void;
  radialGeometry?: { cx: number; cy: number; radius: number };
}

// What every gradient and effect draw function receives.
export type DrawCtx = CanvasDrawParams & DrawFrame;

// A draw context plus what buildEffectCtx adds for one effect in the stack.
export interface EffectFrame {
  effectType: string;
  index: number;
  isFirstEffect: boolean;
  audioModulation: number;
  imageData: ImageData | null;
}
// Effects don't get the clocks only gradients use (the effect context is built without them).
export type EffectCtx = Omit<DrawCtx, 'fieldAnimTime' | 'turrellAnimTime' | 'hatchAnimTime' | 'noiseAnimTime' | 'radialAnimTime'> & EffectFrame;
